// Replace "(문구 추정)" button captions with the GUI status text found by the checkers (_gui/r*.txt: "PROG CODE=text").
import fs from 'node:fs';
const P = 'C:/Users/pssps/Documents/Projects/sc4sap_project/.sc4sap/work/HKT-DEV/processes';
const map = new Map();
for (const f of fs.readdirSync(`${P}/_gui`).filter(f => /^r.*\.txt$/.test(f)))
  for (const l of fs.readFileSync(`${P}/_gui/${f}`, 'utf8').split(/\r?\n/)) { const m = /^(\S+)\s+(\S+)=(.+)$/.exec(l.trim()); if (m && m[3] !== '?') map.set(`${m[1]} ${m[2]}`, m[3].trim()); }
let fixed = 0, left = 0;
const fix = (o) => {
  if (!o?.action || !/문구 추정/.test(o.action)) return;
  const prog = (o.where || '').match(/\b(Z[A-Z0-9_]+|SAPM[A-Z0-9]+)\b/)?.[1];
  const codes = [...o.action.matchAll(/\b([A-Z][A-Z0-9_&%]{1,19})\b/g)].map(m => m[1]);
  const hit = prog && codes.map(c => [c, map.get(`${prog} ${c}`)]).find(([, t]) => t);
  if (!hit) { left++; return; }
  const [code, text] = hit;
  let a = o.action.replace(/\s*\(문구 추정\)/g, '');
  a = /'[^']*'/.test(a) ? a.replace(/'[^']*'/, `'${text}'`) : `'${text}' ${a}`;
  if (!a.includes(code)) a += ` (${code})`;
  o.action = a; fixed++;
};
for (const [M, n] of [['SD', 13], ['FI', 10], ['CO', 7]]) for (let k = 1; k <= n; k++) {
  const f = `${P}/${M}/_state/step5.part-${k}.json`; const p = JSON.parse(fs.readFileSync(f, 'utf8'));
  p.tasks.forEach(t => { (t.task.steps || []).forEach(s => { fix(s); (s.alts || []).forEach(fix); }); (t.task.flow?.nodes || []).forEach(fix); });
  fs.writeFileSync(f, JSON.stringify(p, null, 1));
}
console.log(JSON.stringify({ texts: map.size, fixed, stillEstimated: left }));
