  for (const l of fs.readFileSync(f, 'utf8').split(/\r?\n/)) { const m = /^(\S+)\s+(\S+)=(.+)$/.exec(l.trim()); if (m && m[3].trim() !== '?') map.set(`${m[1]} ${m[2]}`, m[3].trim()); }
const TAG = /\s*\(문구 추정\)|,\s*문구 추정(?=\))/g;
const CODE = '[A-Z][A-Z0-9_&%]*';
let fixed = 0, cleared = 0, left = 0; const log = [];
const fix = (o) => {
  if (!o?.action || !/문구 추정/.test(o.action)) return;
  const prog = (o.where || '').match(/\b(Z[A-Z0-9_]+)\b/)?.[1];
  const before = o.action; let a = before;
  const quotedCodes = [...a.matchAll(new RegExp(`'(${CODE})'`, 'g'))].map(m => m[1]);
  const parenCodes = [...a.matchAll(new RegExp(`\\((${CODE})[,)]`, 'g'))].map(m => m[1]);
  const codes = new Set([...quotedCodes, ...parenCodes].filter(c => !/^(F\d+|P_\w+|X|P\/H)$/.test(c)));
  const texts = new Set(); let unresolved = 0;
  for (const c of codes) {
    const t = prog && map.get(`${prog} ${c}`);
    if (!t) { unresolved++; continue; }
    texts.add(t);
    const labelled = new RegExp(`'[^']*'(\\s*(?:버튼)?\\s*)\\(${c}([,)])`);
    if (labelled.test(a)) a = a.replace(labelled, `'${t}'$1(${c}$2`);
    else a = a.replace(new RegExp(`'${c}'`), `'${t}'(${c})`);
  }
  const otherQuoted = [...a.matchAll(/'([^']*)'/g)].map(m => m[1]).filter(q => !texts.has(q));
  const standardOnly = codes.size === 0 && !/버튼|팝업|송신|보류|상세|처리/.test(a) && otherQuoted.length === 0;
  if ((codes.size && !unresolved && !otherQuoted.length) || standardOnly) {
    a = a.replace(TAG, '').replace(/\(\s*,/g, '(').replace(/\s+\)/g, ')');
    codes.size ? fixed++ : cleared++;
  } else left++;
  if (a !== before) log.push(`${prog || o.where} | ${before}\n   -> ${a}`);
  else if (/문구 추정/.test(a)) log.push(`${prog || o.where} | KEEP | ${a}`);
  o.action = a;
};
for (let k = 1; k <= 12; k++) {
  const f = `${P}/step5.part-${k}.json`; const p = JSON.parse(fs.readFileSync(f, 'utf8'));
  p.tasks.forEach(t => { (t.task.steps || []).forEach(s => { fix(s); (s.alts || []).forEach(fix); }); (t.task.flow?.nodes || []).forEach(fix); });
  if (!dry) { fs.copyFileSync(f, `${f}.bak-gui`); fs.writeFileSync(f, JSON.stringify(p, null, 1)); }
}
fs.writeFileSync('apply-mm-gui.log', log.join('\n'), 'utf8');
console.log(JSON.stringify({ texts: map.size, fixed, cleared, stillEstimated: left, dry }));

